using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.StatisticalMechanics.NoisyVoter;

internal sealed class ConditionalRepetitionMomentsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The native ancestral-pair multiplicities determine both conditional repetition moments.",
        H("Conditional moments of the actual repetition statistic"),
        Blocks(
            Paragraph(Text("Let V and O be arbitrary types, let G be a connected locally finite undirected simple graph with a neighbour at each vertex, and let P be a probability measure on O. The original RepetitionVarianceLinear.Model G P supplies measurable, mutually independent initial opinions, fresh opinions, refresh controls and actual-neighbour choices with the prescribed fair, noisy and uniform marginal laws and with noise strictly between zero and one. Its nvm is the original synchronous recursion: a copy at time n uses the preceding time layer. No stationary or deterministic initial law is substituted.")),
            Paragraph(Text("For a root u, a natural lag d at least one and any natural t, including zero, write W for RepetitionVarianceLinear.W M.coordinate u d t and N=t+d. The source and coin functions are those of AncestralSources on the disjoint native label type Label V. Put a_i=source M.coordinate i u and b_i=source M.coordinate (i+d) u. The real-valued count C M u d t is the sum, over Icc 1 t, of the indicators of a_i=b_i. For a finite label set e, multiplicity M u d t e is the natural cardinality of the indices in Icc 1 t for which a_i differs from b_i and the unordered two-element set containing a_i and b_i equals e. Thus orientation is forgotten, repeated occurrences are counted and coalesced pairs are excluded.")),
            Paragraph(Text("The field H M is the comap of the complete vector of native coordinates c satisfying positiveControl c. These are precisely refresh(n+1,v) and choice(n+1,v), for every natural n and every v in V. The vector has its dependent product sigma-field. Consequently H is exactly the sigma-field generated by all strictly positive-time refresh and neighbour-choice coordinates, including times and vertices outside the observed rectangle. It contains no auxiliary time-zero coordinate by definition. Source labels and the displayed count and multiplicities are H-measurable.")),
            Paragraph(Text("Set E_N=pairs G u N=(RectangularSupport.L G u N).powersetCard 2. The original rectangular support theorem puts all a_i and b_i in this deterministic finite label set. Every nonzero global pair multiplicity therefore belongs to E_N, even on an infinite graph. The character of e is the product, over its labels, of sgn(coin M.coordinate l); for a two-element set it is the product of its two fair signs.")),
            Describe.Lean(DescribeId.Create("native-conditional-repetition-moments"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/NoisyVoter/ConditionalRepetitionMoments.conditional_repetition_moments"),
                H("Both native conditional moment identities"),
                StatementSource.FromAuthor(Statement()),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create(
                    "D5/L/StatisticalMechanics/benjaminihelmantovzhukovskii2023noisyvoter")),
                Blocks(
                    Paragraph(Text("In the displayed statement, AE(P,f,g) means equality of the two real functions P-almost everywhere, and condExp(P,f,H) denotes the conditional expectation P[f|H]. The symbols W, C and m denote exactly the native functions defined above, with m(M,u,d,t,e,w) the natural multiplicity cast to a real number. The second expectation centers by the original conditional expectation of W itself; it is not a variance under a chosen pointwise conditional probability kernel.")),
                    Paragraph(Text("The full positive-control vector is independent of the entire native opinion-coin family by independence of disjoint coordinate subfamilies. Fixed pair-character means and cross means are supplied by fixed_pair_sign_mean and fixed_four_sign_mean at their original owner. Conditional expectation independence turns these into conditional orthogonality on H. This includes identical pairs, disjoint pairs and pairs sharing one label; it assumes neither independence of observed opinions nor joint independence of all pair characters.")),
                    Paragraph(Text("The exact pointwise regrouping of W is (t+C)/2 plus one half of the sum of multiplicity times character. Bounded H-measurable multiplicities pull out of conditional expectations. The first moment removes the character sum, and the square of that sum leaves precisely its diagonal terms. Finite intersections of probability-one events give simultaneous conditional identities without choosing values on zero-probability control histories. The native W is in L2 on the original probability space: W_measurable, W_bound and W_sample_eq apply directly to its coordinate family. Each multiplicity is at most t, so every finite product integrated in the proof is integrable."))),
                DescribeRole.Theorem),
            Paragraph(Text("When t=0, W, C and every multiplicity vanish, and both identities hold as empty-sum statements. Arbitrary finite and infinite connected locally finite graphs remain within the same telescope. The unconditional total-variance formula, its exact nonnegative remainder, its equality criterion and optimality of the universal lower constant require further arguments."))), []));

    private static Formula X(string n) => F.Id(n);
    private static Formula Named(string n) => Seq(Operatorname, Grp(X(n)));
    private static Formula Call(string n, params Formula[] a) => new Formula.Apply(Named(n), [.. a]);
    private static Formula All(string n, Formula t, Formula b) =>
        new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(n), t, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula Leq(Formula a, Formula b) =>
        new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula Nat() => Seq(Mathbb, Grp(X("N")));
    private static Formula Real() => Seq(Mathbb, Grp(X("R")));
    private static Formula Lam(string n, Formula b) => Seq(Open, X(n), Colon, X("O"), Sp, Mapsto, Sp, b, Close);
    private static Formula Add(Formula a, Formula b) => Seq(a, Plus, b);
    private static Formula Mul(Formula a, Formula b) => Seq(a, Sp, Times, Sp, b);
    private static Formula Div(Formula a, Formula b) => Seq(Frac, Grp(a), Grp(b));
    private static Formula Sq(Formula a) => Seq(Open, a, Close, Caret, Grp(D(2)));
    private static Formula W() => Call("W", Call("coordinate", X("M")), X("u"), X("d"), X("t"));
    private static Formula HField() => Call("H", X("M"));
    private static Formula Mean() => Call("condExp", X("P"), W(), HField());
    private static Formula At(Formula f) => new Formula.Apply(f, [X("w")]);
    private static Formula Statement()
    {
        var c = Call("C", X("M"), X("u"), X("d"), X("t"), X("w"));
        var center = Lam("w", Div(Add(Call("cast", X("t"), Real()), c), D(2)));
        var first = Call("AE", X("P"), Mean(), center);
        var square = Lam("w", Sq(Seq(At(W()), Minus, At(Mean()))));
        var e = Call("pairs", X("G"), X("u"), Add(X("t"), X("d")));
        var m = Call("m", X("M"), X("u"), X("d"), X("t"), X("e"), X("w"));
        var sum = Seq(Sum, Underscore, Grp(Seq(X("e"), Sp, InMacro, Sp, e)), Sq(m));
        var second = Call("AE", X("P"), Call("condExp", X("P"), square, HField()),
            Lam("w", Mul(Div(D(1), D(4)), sum)));
        var body = All("P", Call("Measure", X("O")),
            All("M", Call("Model", X("G"), X("P")), All("u", X("V"),
            All("d", Nat(), All("t", Nat(), Imp(Leq(D(1), X("d")), And(first, second)))))));
        return Disp(All("V", Named("Type"), All("O", Named("Type"),
            All("G", Call("SimpleGraph", X("V")),
                Seq(OpenBracket, Call("LocallyFinite", X("G")), CloseBracket, Sp,
                    OpenBracket, Call("MeasurableSpace", X("O")), CloseBracket, Sp, body)))));
    }
}
